/**
 * The branch whose paper a given account is on, or null for «the usual paper».
 *
 * The stored branch is free text — it can be a code, a name, «AL MAKTOUM - 2624»,
 * or empty — so matching is deliberately forgiving: a bare number matches a code,
 * and anything else matches an alias appearing anywhere in the string. It is
 * never a guess: no match means null, and null means the regional office set,
 * NOT «probably the nearest branch».
 */
export function branchFor(raw: string | null | undefined): CaseBranch | null {
  const s = String(raw || '').trim().toLowerCase()
  if (!s) return null
  for (const b of CASE_BRANCHES) if (s === b.code) return b
  const digits: string[] = s.match(/\d{3,}/g) || []
  for (const b of CASE_BRANCHES) if (digits.includes(b.code)) return b
  for (const b of CASE_BRANCHES) {
    if (b.aliases.some((a) => a.length > 2 && s.includes(a))) return b
  }
  return null
}

/** The senders the dropdown offers: the two standing ones, then every branch. */
export const BRANCH_SENDERS: string[] = CASE_BRANCHES.map((b) => b.sender)

/**
 * The branch a signature line names — the OTHER direction, and the one that
 * decides the paper.
 *
 * The signature line is what the owner actually controls: «با تغییر اون قسمت در
 * انتهای نامه از لیست هم باید سربرگ و فوتر مناسب همون شعبه بشن». The account
 * merely pre-selects it. Anything that is not a branch (the two house
 * signatories, or an old letter's free text) returns null, which means the
 * facilities paper.
 */
export function branchBySender(sender: string | null | undefined): CaseBranch | null {
  const s = String(sender || '').trim()
  if (!s) return null
  return CASE_BRANCHES.find((b) => b.sender === s) ?? null
}

/** The branch's own paper, or null when we do not hold it yet. A branch with a
 *  partial set is treated as having none: half a letterhead is not a letterhead. */
export function paperOf(b: CaseBranch | null | undefined) {
  if (!b || !b.logo || !b.name || !b.footer) return null
  return { logo: b.logo, name: b.name, footer: b.footer, logoBox: b.logoBox }
}
